  "Sundays": { es: "Domingos", pt: "Domingos" },
  "Tables ({count}) became plain paragraphs, cell by cell.": { es: "Las tablas ({count}) se convirtieron en párrafos, celda por celda.", pt: "As tabelas ({count}) viraram parágrafos, célula por célula." },
