  "Blanks": { es: "Espacios en blanco", pt: "Lacunas" },
  "Blanks go in your own words, not in a quotation. Change it to a paragraph or remove the [[ ]] marks.": { es: "Los espacios en blanco van en tus propias palabras, no en una cita. Cámbiala a párrafo o quita las marcas [[ ]].", pt: "As lacunas ficam nas suas próprias palavras, não em uma citação. Mude para parágrafo ou tire as marcas [[ ]]." },
  "Blanks go in your own words, not in a quotation. Remove the blank from the quotation.": { es: "Los espacios en blanco van en tus propias palabras, no en una cita. Quita el espacio de la cita.", pt: "As lacunas ficam nas suas próprias palavras, não em uma citação. Tire a lacuna da citação." },
  "Check Answers": { es: "Revisar respuestas", pt: "Conferir respostas" },
  "Correct": { es: "Correcto", pt: "Correto" },
  "Fill in the blanks as you listen. Your answers are saved in this browser, and you can check them once the church shares the answers.": { es: "Llena los espacios mientras escuchas. Tus respuestas se guardan en este navegador, y podrás revisarlas cuando la iglesia comparta las respuestas.", pt: "Preencha as lacunas enquanto ouve. Suas respostas ficam salvas neste navegador, e você pode conferi-las quando a igreja compartilhar as respostas." },
  "Fill in the blanks as you listen. Your answers are saved in this browser.": { es: "Llena los espacios mientras escuchas. Tus respuestas se guardan en este navegador.", pt: "Preencha as lacunas enquanto ouve. Suas respostas ficam salvas neste navegador." },
  "Fill-in-the-blank answers": { es: "Respuestas de los espacios en blanco", pt: "Respostas das lacunas" },
  "For blanks members fill in with their own words. Nothing is checked.": { es: "Para espacios que los miembros llenan con sus propias palabras. No se revisa nada.", pt: "Para lacunas que os membros preenchem com as próprias palavras. Nada é conferido." },
  "Give each blank its answer, or make it an open blank.": { es: "Dale a cada espacio su respuesta, o hazlo un espacio abierto.", pt: "Dê a cada lacuna a sua resposta, ou faça dela uma lacuna aberta." },
  "Give every blank its answer, or make it an open blank.": { es: "Dale a cada espacio en blanco su respuesta, o hazlo un espacio abierto.", pt: "Dê a cada lacuna a sua resposta, ou faça dela uma lacuna aberta." },
  "Hide Answers": { es: "Ocultar respuestas", pt: "Ocultar respostas" },
  "Hint (optional)": { es: "Pista (opcional)", pt: "Dica (opcional)" },
  "Make Blank": { es: "Hacer espacio en blanco", pt: "Criar lacuna" },
  "Members can check their answers as soon as the sermon is published.": { es: "Los miembros pueden revisar sus respuestas en cuanto se publique el sermón.", pt: "Os membros podem conferir as respostas assim que o sermão for publicado." },
  "Members can check their answers now.": { es: "Los miembros ya pueden revisar sus respuestas.", pt: "Os membros já podem conferir as respostas." },
  "Members write their own words": { es: "Los miembros escriben sus propias palabras", pt: "Os membros escrevem as próprias palavras" },
  "Never": { es: "Nunca", pt: "Nunca" },
