  "Outline › Blanks": { es: "Bosquejo › Espacios en blanco", pt: "Esboço › Lacunas" },
  "Practice Again": { es: "Practicar de nuevo", pt: "Praticar de novo" },
  "Practicing: a fresh try. Your saved answers are kept.": { es: "Practicando: un intento nuevo. Tus respuestas guardadas se conservan.", pt: "Praticando: uma nova tentativa. Suas respostas salvas continuam guardadas." },
  "Publish the sermon first, then reveal its answers.": { es: "Publica primero el sermón y luego muestra sus respuestas.", pt: "Publique o sermão primeiro e depois mostre as respostas." },
  "Remove blank": { es: "Quitar espacio", pt: "Remover lacuna" },
  "Reveal Answers": { es: "Mostrar respuestas", pt: "Mostrar respostas" },
  "Right away": { es: "De inmediato", pt: "Imediatamente" },
  "Select the words members should fill in, then choose Make Blank.": { es: "Selecciona las palabras que los miembros deben llenar y elige Hacer espacio en blanco.", pt: "Selecione as palavras que os membros devem preencher e escolha Criar lacuna." },
  "Show Answers": { es: "Ver respuestas", pt: "Ver respostas" },
